	"vendordoclines/i18n/i18n.properties":'appTitle=Vendor Reconciliation Dashboard\r\nappDescription=Reconcile extracted vendor invoices against SAP S/4HANA\r\n\r\n# Header\r\ndashboardTitle=Vendor Reconciliation Dashboard\r\ndashboardSubtitle=Real-time reconciliation of extracted vendor invoices against SAP S/4HANA\r\ntimeRangeLabel=Time range\r\ntimeRange24h=Last 24 hours\r\ntimeRange7d=Last 7 days\r\ntimeRange30d=Last 30 days\r\nbtnTriggerRun=Trigger new run\r\nbtnRefresh=Refresh\r\n\r\n# KPIs\r\nkpiTotalInvoices=Total Invoices\r\nkpiAutoMatched=Auto-Matched\r\nkpiMismatches=Mismatches\r\nkpiMissingInS4=Missing in S/4\r\nkpiMissingInFile=Missing in File\r\nkpiDuplicates=Duplicates\r\nkpiHighValue=High-Value Exceptions\r\nkpiBlocked=Blocked\r\nkpiAvgProcessing=Avg. Processing Time\r\nkpiOcrAccuracy=OCR Accuracy\r\n\r\n# Charts\r\nchartStatusDist=Reconciliation Status Distribution\r\nchartMismatchVendor=Top 10 Vendors by Mismatch\r\nchartTrend=Daily Reconciliation Trend\r\nchartVarianceType=Variance Type Breakdown\r\n\r\n# Table\r\ntableTitle=Reconciliation Results\r\nsearchPlaceholder=Search invoice, vendor, PO...\r\ncolVendor=Vendor\r\ncolInvoiceFile=Invoice # (File)\r\ncolInvoiceS4=Invoice # (S/4)\r\ncolPO=PO\r\ncolGR=GR\r\ncolFileGross=File Gross\r\ncolS4Gross=S/4 Gross\r\ncolVariance=Variance\r\ncolVariancePct=Var %\r\ncolStatus=Status\r\ncolAssigned=Assigned\r\ncolActions=Actions\r\n\r\n# Object Page\r\nopBack=Back\r\nopAiIndicators=AI Indicators\r\nopOcrConf=OCR Confidence\r\nopAutoResolve=Auto-Resolve Eligible\r\nopSuggested=Suggested Category\r\nopConfidence=Confidence\r\nopHeaderComp=Header Comparison\r\nopFileExtract=File Extract\r\nopS4Invoice=SAP S/4HANA Invoice\r\nopLineItems=Line Item Comparison\r\nopVarianceBreakdown=Variance Breakdown\r\nopProcessingLogs=Processing Logs\r\nopAuditTrail=Audit Trail\r\nopVendorInvoice=Vendor Invoice\r\nopDownloadPdf=Download PDF\r\nopOpenInNewTab=Open in New Tab\r\nopInvoicePdfNotReady=Vendor invoice PDF is being generated\\u2026\r\nopRecommendedActions=Recommended Actions\r\nopAccept=Accept Match\r\nopReject=Reject Match\r\nopEscalate=Escalate\r\nopDispute=Create Dispute\r\n\r\n# Action feedback\r\nmsgAccepted=Match accepted\r\nmsgRejected=Match rejected\r\nmsgEscalated=Escalated to {0}\r\nmsgDisputed=Dispute created\r\nmsgActionFailed=Action failed: {0}\r\n',
